exercises.solution:
package main

import "fmt"


func main() {
    matrix := [2][2]int{{1, 2}, {3, 4}}
    for _, row := range matrix {
        for _, val := range row {
            fmt.Println(val)
        }
    }
}

exercises.starter_code:
package main

import "fmt"

func main() {
    arr := [5]int{10, 20, 30, 40, 50}
    // Compute sum of all elements

    // Print sum
}

exercises.solution:
package main

import "fmt"

func main() {
    arr := [5]int{10, 20, 30, 40, 50}
    sum := 0
    for _, v := range arr {
        sum += v
    }
    fmt.Println(sum)
}

